"""Test candidate feed URLs from GitHub's servers and write digest/probe.md."""
import urllib.request, re
from pathlib import Path
UA = "Mozilla/5.0 (compatible; FieldNotesFeedCollector/1.0)"
C = {'FEMA': ['https://www.fema.gov/feeds/news.rss', 'https://www.fema.gov/news-release/rss.xml', 'https://www.fema.gov/rss/press.rss'], 'HSToday': ['https://www.hstoday.us/feed/'], 'Domestic Preparedness': ['https://domesticpreparedness.com/feed', 'https://www.domesticpreparedness.com/rss'], 'Emergency Management (GovTech)': ['https://www.govtech.com/em/rss.xml', 'https://www.govtech.com/em.rss', 'https://www.govtech.com/rss/em'], 'GovTech public safety': ['https://www.govtech.com/public-safety/rss.xml', 'https://www.govtech.com/public-safety.rss'], 'Crisis Response Journal': ['https://www.crisis-response.com/feed', 'https://www.crisis-response.com/rss'], 'EENA': ['https://eena.org/feed/'], 'APCO IntelliComm': ['https://intellicomm.apcointl.org/feed/', 'https://www.apcointl.org/feed/'], 'NENA': ['https://www.nena.org/news/rss.aspx?type=1', 'https://www.nena.org/feed'], 'RadioResource': ['https://www.rrmediagroup.com/rss/news', 'https://www.rrmediagroup.com/RSS'], 'Firehouse': ['https://www.firehouse.com/__rss/website-scheduled-content.xml?input=%7B%22sectionAlias%22%3A%22home%22%7D'], 'FireRescue1': ['https://www.firerescue1.com/rss/', 'https://www.firerescue1.com/feed'], 'The Conversation CA': ['https://theconversation.com/ca/topics/natural-disasters-1172/articles.atom', 'https://theconversation.com/ca/topics/emergency-management-26773/articles.atom'], 'GDACS': ['https://www.gdacs.org/xml/rss_24h.xml', 'https://www.gdacs.org/xml/rss.xml'], 'WMO': ['https://wmo.int/rss.xml', 'https://wmo.int/news/rss.xml'], 'Canadian Red Cross': ['https://www.redcross.ca/rss/news', 'https://www.redcross.ca/feed'], 'ICLR': ['https://www.iclr.org/feed/'], 'Intact Centre': ['https://www.intactcentreclimateadaptation.ca/feed/'], 'NHESS': ['https://nhess.copernicus.org/xml/rss2_0.xml'], 'RHCPP (Wiley)': ['https://onlinelibrary.wiley.com/feed/19444079/most-recent'], 'Crossref JHSEM': ['https://api.crossref.org/journals/1547-7355/works?sort=created&order=desc&rows=5'], 'Crossref IJMED': ['https://api.crossref.org/journals/0280-7270/works?sort=created&order=desc&rows=5'], 'Crossref DMPHP': ['https://api.crossref.org/journals/1935-7893/works?sort=created&order=desc&rows=5'], 'Crossref Weather Climate Society': ['https://api.crossref.org/journals/1948-8327/works?sort=created&order=desc&rows=5'], 'Crossref Environmental Hazards': ['https://api.crossref.org/journals/1747-7891/works?sort=created&order=desc&rows=5'], 'Crossref Journal of Risk Research': ['https://api.crossref.org/journals/1366-9877/works?sort=created&order=desc&rows=5'], 'GN community risk': ['https://news.google.com/rss/search?q=(%22community+risk+assessment%22+OR+%22community+risk+reduction%22+OR+%22hazard+identification+and+risk+assessment%22)+when:7d&hl=en-CA&gl=CA&ceid=CA:en'], 'GN alerting': ['https://news.google.com/rss/search?q=(%22Alert+Ready%22+OR+%22emergency+alert%22+OR+%22public+alerting%22+OR+%22wireless+emergency+alert%22)+when:7d&hl=en-CA&gl=CA&ceid=CA:en'], 'GN public safety comms': ['https://news.google.com/rss/search?q=(%22public+safety+broadband%22+OR+FirstNet+OR+%22public+safety+communications%22+OR+%22emergency+communications%22)+when:7d&hl=en-CA&gl=CA&ceid=CA:en'], 'GN EM technology': ['https://news.google.com/rss/search?q=(%22emergency+management%22+OR+%22disaster+response%22+OR+firefighters)+(AI+OR+drones+OR+%22artificial+intelligence%22+OR+technology)+when:7d&hl=en-CA&gl=CA&ceid=CA:en'], 'GN resilience policy': ['https://news.google.com/rss/search?q=(%22disaster+resilience%22+OR+%22climate+adaptation%22+OR+%22disaster+risk+reduction%22)+(policy+OR+strategy+OR+funding)+Canada+when:7d&hl=en-CA&gl=CA&ceid=CA:en']}
out = ["# Probe results", "", "| Feed | URL | Result |", "|---|---|---|"]
for name, urls in C.items():
    for u in urls:
        try:
            req = urllib.request.Request(u, headers={"User-Agent": UA})
            b = urllib.request.urlopen(req, timeout=20).read()
            t = b[:3000].decode("utf-8", "ignore")
            kind = "rss/atom" if re.search(r"<(rss|feed|rdf)", t) else ("json" if t.lstrip().startswith("{") else "html/other")
            n = len(re.findall(rb"<(item|entry)[ >]", b)) if kind == "rss/atom" else (b.count(b'"DOI"') if kind == "json" else 0)
            m = re.findall(rb"<(?:pubDate|updated|published|dc:date)>([^<]{6,40})<", b)
            res = f"ok · {kind} · {n} items · newest {m[0].decode('utf-8','ignore')[:25] if m else '?'}"
        except Exception as e:
            res = f"FAIL {type(e).__name__} {str(e)[:60]}"
        out.append(f"| {name} | {u} | {res} |")
Path("digest").mkdir(exist_ok=True)
Path("digest/probe.md").write_text("\n".join(out) + "\n")
print("\n".join(out))
